 function experiments(m){const tasks=state.tasks.filter(t=>t.module===m.id);return '<div class="card">'+table(['任务','版本与产物','当前步骤','操作'],tasks.map(t=>['<strong>'+e(t.name)+'</strong><span class="fine">'+t.id+'</span>','v'+t.revision+' · '+Object.keys(t.outputs).length+' 项产物',e(shortSteps[t.current]),button('打开任务','open-task',t.id)+button('查看档案','task-archive',t.id)]))+'</div>';}
